CREATE TABLE IF NOT EXISTS governed_creator_engagements(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,campaign_ref TEXT NOT NULL,creator_ref TEXT NOT NULL,identity_evidence JSONB NOT NULL DEFAULT '{}'::jsonb,audience_evidence JSONB NOT NULL DEFAULT '{}'::jsonb,brief_version TEXT,rights_version TEXT,disclosure_approved BOOLEAN NOT NULL DEFAULT false,contract_reference TEXT,content_reference TEXT,platform_receipt TEXT,payment_reference TEXT,payee_owner_id BIGINT,attribution JSONB,status TEXT NOT NULL DEFAULT 'discovery',idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,created_by BIGINT NOT NULL,approved_by BIGINT,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,campaign_ref,creator_ref),UNIQUE(tenant_id,idempotency_key),CHECK(status IN ('discovery','vetted','briefed','contracted','content_review','approved','published','reconciled','closed')));
CREATE TABLE IF NOT EXISTS influencer_integration_runs(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,provider TEXT NOT NULL,operation TEXT NOT NULL,status TEXT NOT NULL,data_as_of TIMESTAMPTZ,external_reference TEXT,error_code TEXT,error_message TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(status IN ('queued','succeeded','failed','stale','manual_review')));
CREATE TABLE IF NOT EXISTS influencer_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,actor_user_id BIGINT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,before_state JSONB,after_state JSONB,request_id TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
